import React, { useState } from 'react';
import Aura from '../components/Aura';
import { useMoods } from '../hooks/useStorage';

const GOLD = '#C8A96E';
const s = { label: { fontFamily: 'DM Mono, monospace', fontSize: 9, letterSpacing: '0.22em', textTransform: 'uppercase', color: 'rgba(237,233,224,0.3)' } };

const MOODS = [
  { score: 1, emoji: '😔', label: 'Väldigt dåligt', c1: '#5C1A1A', c2: '#8B2020' },
  { score: 2, emoji: '😟', label: 'Dåligt',         c1: '#5C2A10', c2: '#8B3A15' },
  { score: 3, emoji: '😐', label: 'Okej',           c1: '#3A3010', c2: '#6B5515' },
  { score: 4, emoji: '🙂', label: 'Bra',            c1: '#0F3A22', c2: '#1A6B3A' },
  { score: 5, emoji: '😄', label: 'Väldigt bra',    c1: '#0F2A4A', c2: '#1A4A8B' },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [selected, setSelected] = useState(null);
  const [note,     setNote]     = useState('');
  const [step,     setStep]     = useState('pick');
  const activeM = selected !== null ? MOODS[selected] : MOODS[2];

  const save = () => { const m = MOODS[selected]; addMood(m.score, m.emoji, m.label, note); setStep('done'); };

  if (todayChecked && step !== 'done') return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={['#0F2A4A', '#1A4A8B']} intensity={0.5} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '0 32px' }}>
        <p style={{ ...s.label, marginBottom: 16 }}>Redan incheckad</p>
        <h2 style={{ fontSize: 36, fontWeight: 800, letterSpacing: '-0.04em', color: '#ede9e0', marginBottom: 28 }}>Kom tillbaka imorgon</h2>
        <div style={{ display: 'flex', gap: 10 }}>
          <button onClick={() => setPage('history')} style={{ padding: '13px 24px', borderRadius: 100, background: '#ede9e0', color: '#080808', fontSize: 13, fontWeight: 700, border: 'none' }}>Historik</button>
          <button onClick={() => setPage('home')} style={{ padding: '13px 24px', borderRadius: 100, background: 'rgba(255,255,255,0.07)', border: '0.5px solid rgba(255,255,255,0.12)', color: 'rgba(237,233,224,0.6)', fontSize: 13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'done') return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={[activeM.c1, activeM.c2]} intensity={0.65} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '0 32px' }}>
        <div style={{ fontSize: 56, marginBottom: 18 }}>{MOODS[selected].emoji}</div>
        <p style={{ ...s.label, marginBottom: 10, color: GOLD }}>Sparat</p>
        <h2 style={{ fontSize: 'clamp(28px,8vw,44px)', fontWeight: 800, letterSpacing: '-0.04em', color: '#ede9e0', marginBottom: 36 }}>{MOODS[selected].label}</h2>
        <div style={{ display: 'flex', gap: 10 }}>
          <button onClick={() => setPage('history')} style={{ padding: '13px 24px', borderRadius: 100, background: '#ede9e0', color: '#080808', fontSize: 13, fontWeight: 700, border: 'none' }}>Historik</button>
          <button onClick={() => setPage('home')} style={{ padding: '13px 24px', borderRadius: 100, background: 'rgba(255,255,255,0.07)', border: '0.5px solid rgba(255,255,255,0.12)', color: 'rgba(237,233,224,0.6)', fontSize: 13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'note') return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={[activeM.c1, activeM.c2]} intensity={0.6} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', padding: '36px 22px', paddingBottom: 100 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 40 }}>
          <span style={s.label}>Check-in</span>
          <button onClick={() => setStep('pick')} style={{ ...s.label, color: 'rgba(237,233,224,0.3)' }}>← Ändra</button>
        </div>
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center' }}>
          <div style={{ fontSize: 60, marginBottom: 16 }}>{MOODS[selected].emoji}</div>
          <h2 style={{ fontSize: 'clamp(28px,8vw,44px)', fontWeight: 800, letterSpacing: '-0.04em', color: '#ede9e0', marginBottom: 6 }}>{MOODS[selected].label}</h2>
          <p style={{ ...s.label, marginBottom: 36 }}>Hur kändes det?</p>
          <div style={{ width: '100%', background: 'rgba(14,14,14,0.9)', backdropFilter: 'blur(24px)', borderRadius: 22, padding: '16px 18px', border: '0.5px solid rgba(255,255,255,0.1)', marginBottom: 14 }}>
            <textarea value={note} onChange={e => setNote(e.target.value)} maxLength={255}
              placeholder="Valfri notering om dagen..."
              style={{ width: '100%', background: 'transparent', border: 'none', color: 'rgba(237,233,224,0.8)', fontSize: 15, fontWeight: 400, resize: 'none', height: 80, outline: 'none', lineHeight: 1.7 }} />
          </div>
          <button onClick={save} style={{ width: '100%', padding: '15px', borderRadius: 100, background: '#ede9e0', color: '#080808', fontSize: 14, fontWeight: 700, border: 'none', boxShadow: '0 8px 32px rgba(0,0,0,0.4)' }}>
            Spara →
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={[activeM.c1, activeM.c2]} intensity={selected !== null ? 0.6 : 0.4} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', padding: '36px 22px', paddingBottom: 100 }}>
        <div style={{ marginBottom: 'auto' }}>
          <p style={s.label}>Hur mår du idag?</p>
          <h1 style={{ fontSize: 'clamp(32px,9vw,52px)', fontWeight: 800, letterSpacing: '-0.05em', lineHeight: 1.05, color: '#ede9e0', marginTop: 8 }}>Välj ett<br />humör</h1>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginBottom: 14 }}>
          {[...MOODS].reverse().map((m, i) => {
            const idx = 4 - i;
            const isSel = selected === idx;
            return (
              <button key={m.score}
                onMouseEnter={() => setSelected(idx)}
                onClick={() => setSelected(idx)}
                style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '14px 16px', borderRadius: 16, background: isSel ? 'rgba(200,169,110,0.1)' : 'rgba(255,255,255,0.04)', border: `0.5px solid ${isSel ? 'rgba(200,169,110,0.3)' : 'rgba(255,255,255,0.07)'}`, transition: 'all .22s cubic-bezier(0.16,1,0.3,1)', backdropFilter: 'blur(12px)', cursor: 'pointer', textAlign: 'left' }}>
                <span style={{ fontSize: 22, width: 34, textAlign: 'center' }}>{m.emoji}</span>
                <span style={{ fontSize: 15, fontWeight: isSel ? 600 : 400, color: isSel ? '#ede9e0' : 'rgba(237,233,224,0.45)', flex: 1, transition: 'all .2s' }}>{m.label}</span>
                {isSel && <span style={{ color: GOLD, fontSize: 12 }}>→</span>}
              </button>
            );
          })}
        </div>

        <button onClick={() => selected !== null && setStep('note')} disabled={selected === null}
          style={{ width: '100%', padding: '15px', borderRadius: 100, background: selected !== null ? '#ede9e0' : 'rgba(255,255,255,0.07)', color: selected !== null ? '#080808' : 'rgba(237,233,224,0.25)', fontSize: 14, fontWeight: 700, border: 'none', transition: 'all .3s', opacity: selected === null ? 0.3 : 1 }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}
